        <button class="tab" data-id="Tall Rat XL Caging">Tall Rat XL Caging</button>
      </div>

      <!-- CONTENT -->
      <div id="dynamic-content-area">
        <h1 class="title" id="dynamic-title">Rat Caging</h1>
        <p class="description" id="dynamic-description"></p>
      </div>

    </div>
  </div>
